INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.414, 1, "2030/01/01 14:59:59", -416.5, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 190801, 2, 1, "2025/01/31 12:00:00", "カリン", 1000001, 1, 0.0, 62);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.099, 1, "2030/01/01 14:59:59", -416.5, "ミッションをクリアして、\n報酬をゲットしましょう！", 190801, 2, 2, "2025/01/31 12:00:00", "カリン", 1000002, 1, 0.0, 62);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.801, 1, "2030/01/01 14:59:59", -416.5, "受け取ることができる\n報酬があるようです\n確認してみてください", 190801, 2, 3, "2025/01/31 12:00:00", "カリン", 1000003, 1, 0.0, 63);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (0.0, 2, "2030/01/01 14:59:59", -416.5, "報酬がもらえますよ！\nチェックしてみてください", 190801, 2, 4, "2025/01/31 12:00:00", "カリン", 1000004, 1, 0.0, 63);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.12, 2, "2030/01/01 14:59:59", -363.0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 190801, 1, 5, "2025/01/31 12:00:00", "カリン", 1000005, 1, 0.0, 64);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1.68, 1, "2030/01/01 14:59:59", -363.0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 190801, 2, 6, "2025/01/31 12:00:00", "カリン", 1000006, 1, 0.0, 64);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.33, 2, "2030/01/01 14:59:59", -363.0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 190801, 1, 7, "2025/01/31 12:00:00", "カリン", 1000007, 1, 0.0, 64);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.18, 3, "2030/01/01 14:59:59", -285.0, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 133701, 7, 101, "2025/01/31 12:00:00", "ラビリスタ", 1020101, 10201, -6.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.77, 1, "2030/01/01 14:59:59", -285.0, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 133901, 2, 201, "2025/01/31 12:00:00", "クリスティーナ", 1020102, 10201, -2.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (15.5, 6, "2030/01/01 14:59:59", -285.0, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 133801, 1, 301, "2025/01/31 12:00:00", "ネネカ", 1020103, 10201, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9.061, 2, "2030/01/01 14:59:59", -285.0, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 134301, 5, 101, "2025/02/28 12:00:00", "ランファ", 1020201, 10202, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.699, 1, "2030/01/01 14:59:59", -285.0, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 134401, 2, 201, "2025/02/28 12:00:00", "チカ", 1020202, 10202, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.595, 1, "2030/01/01 14:59:59", -285.0, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 134601, 2, 101, "2025/03/31 12:00:00", "アオイ", 1020301, 10203, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.758, 1, "2030/01/01 14:59:59", -285.0, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 134501, 2, 201, "2025/03/31 12:00:00", "クローチェ", 1020302, 10203, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.0, 2, "2030/01/01 14:59:59", -285.0, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 132302, 6, 101, "2025/04/30 12:00:00", "ルイズマリー", 1020401, 10204, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.904, 1, "2030/01/01 14:59:59", -285.0, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 132402, 2, 201, "2025/04/30 12:00:00", "イロハ", 1020402, 10204, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.487, 4, "2030/01/01 14:59:59", -285.0, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 132502, 2, 301, "2025/04/30 12:00:00", "ソノ", 1020403, 10204, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.763, 1, "2030/01/01 14:59:59", -285.0, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 134901, 2, 101, "2025/05/31 12:00:00", "カノン", 1020502, 10205, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.417, 1, "2030/01/01 14:59:59", -285.0, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 134801, 3, 201, "2025/05/31 12:00:00", "ツムギ", 1020503, 10205, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (10.335, 3, "2030/01/01 14:59:59", -285.0, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 135001, 7, 101, "2025/06/30 12:00:00", "エリス", 1020601, 10206, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.281, 2, "2030/01/01 14:59:59", -285.0, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 135101, 4, 201, "2025/06/30 12:00:00", "シェフィ", 1020602, 10206, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (12.244, 1, "2030/01/01 14:59:59", -285.0, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 135201, 2, 301, "2025/06/30 12:00:00", "プレシア", 1020603, 10206, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.339, 2, "2030/01/01 14:59:59", -285.0, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 135301, 8, 101, "2025/07/31 12:00:00", "クリア", 1020701, 10207, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.184, 7, "2030/01/01 14:59:59", -285.0, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 135401, 9, 201, "2025/07/31 12:00:00", "アネモネ", 1020702, 10207, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.906, 9, "2030/01/01 14:59:59", -285.0, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 129101, 2, 101, "2025/08/31 12:00:00", "アイラ", 1020801, 10208, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (14.465, 1, "2030/01/01 14:59:59", -285.0, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 129201, 2, 201, "2025/08/31 12:00:00", "シナツ", 1020802, 10208, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.662, 4, "2030/01/01 14:59:59", -285.0, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 100101, 3, 301, "2025/08/31 12:00:00", "ヒヨリ", 1020803, 10208, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (10.915, 1, "2030/01/01 14:59:59", -285.0, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 100301, 3, 401, "2025/08/31 12:00:00", "レイ", 1020804, 10208, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.042, 1, "2030/01/01 14:59:59", -285.0, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 135802, 7, 101, "2025/09/30 12:00:00", "ユキノ", 1020901, 10209, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9.402, 4, "2030/01/01 14:59:59", -285.0, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 135903, 1, 201, "2025/09/30 12:00:00", "サツキ", 1020902, 10209, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.16, 8, "2030/01/01 14:59:59", -285.0, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 136902, 1, 301, "2025/09/30 12:00:00", "ルルィ", 1020903, 10209, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.0, 3, "2030/01/01 14:59:59", -285.0, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 137401, 2, 101, "2025/10/31 12:00:00", "カスミ", 1021001, 10210, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.12, 4, "2030/01/01 14:59:59", -285.0, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 136001, 1, 201, "2025/10/31 12:00:00", "アラクネ", 1021002, 10210, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.386, 4, "2030/01/01 14:59:59", -285.0, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 136202, 2, 301, "2025/10/31 12:00:00", "ナーナ", 1021003, 10210, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.438, 3, "2030/01/01 14:59:59", -285.0, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 136402, 4, 101, "2025/11/30 12:00:00", "ユイ", 1021101, 10211, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.35, 1, "2030/01/01 14:59:59", -285.0, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 136302, 5, 201, "2025/11/30 12:00:00", "ミソラ", 1021102, 10211, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.0, 1, "2030/01/01 14:59:59", -285.0, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 136501, 2, 101, "2025/12/31 12:00:00", "シズル", 1021201, 10212, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.25, 1, "2030/01/01 14:59:59", -285.0, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 137902, 2, 201, "2025/12/31 12:00:00", "リノ", 1021202, 10212, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.5, 1, "2030/01/01 14:59:59", -285.0, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 106801, 2, 301, "2025/12/31 12:00:00", "ラビリスタ", 1021203, 10212, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.204, 1, "2030/01/01 14:59:59", -285.0, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 126501, 2, 101, "2026/01/31 12:00:00", "ライラエル", 1021301, 10213, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.176, 1, "2030/01/01 14:59:59", -285.0, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 129701, 2, 201, "2026/01/31 12:00:00", "ネフィ＝ネラ", 1021302, 10213, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.602, 1, "2030/01/01 14:59:59", -285.0, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 133101, 5, 301, "2026/01/31 12:00:00", "ヴァイオレット", 1021303, 10213, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (10.14, 1, "2030/01/01 14:59:59", -285.0, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 138101, 3, 102, "2026/02/06 12:00:00", "ライラエル", 1021304, 10213, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (10.152, 1, "2030/01/01 14:59:59", -285.0, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 138201, 7, 202, "2026/02/06 12:00:00", "ネフィ＝ネラ", 1021305, 10213, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9.688, 4, "2030/01/01 14:59:59", -285.0, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 138001, 3, 302, "2026/02/06 12:00:00", "ヴァイオレット", 1021306, 10213, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.928, 2, "2030/01/01 14:59:59", -285.0, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 138301, 1, 401, "2026/02/12 12:00:00", "ペコリーヌ", 1021307, 10213, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9.19, 4, "2030/01/01 14:59:59", -285.0, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 138702, 2, 101, "2026/02/28 12:00:00", "ワカナ", 1021401, 10214, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.724, 1, "2030/01/01 14:59:59", -285.0, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 138802, 3, 201, "2026/02/28 12:00:00", "シオリ", 1021402, 10214, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.758, 4, "2030/01/01 14:59:59", -285.0, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 138902, 1, 101, "2026/03/31 12:00:00", "グレイス", 1021501, 10215, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.375, 6, "2030/01/01 14:59:59", -285.0, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 139002, 4, 201, "2026/03/31 12:00:00", "キョウカ", 1021502, 10215, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.173, 6, "2030/01/01 14:59:59", -285.0, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 136902, 1, 301, "2026/03/31 12:00:00", "ルルィ", 1021503, 10215, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4.202, 6, "2030/01/01 14:59:59", -285.0, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 139202, 2, 101, "2026/04/30 12:00:00", "ミホ", 1021601, 10216, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.842, 6, "2030/01/01 14:59:59", -285.0, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 139302, 1, 201, "2026/04/30 12:00:00", "マホ", 1021602, 10216, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4.598, 4, "2030/01/01 14:59:59", -285.0, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 139402, 1, 301, "2026/04/30 12:00:00", "エリカ", 1021603, 10216, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.533, 4, "2030/01/01 14:59:59", -285.0, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 125802, 3, 101, "2026/05/31 12:00:00", "リリ", 1021701, 10217, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.0, 3, "2030/01/01 14:59:59", -285.0, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 126102, 3, 301, "2026/05/31 12:00:00", "プレシア", 1021702, 10217, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.214, 3, "2030/01/01 14:59:59", -285.0, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 126002, 4, 201, "2026/05/31 12:00:00", "クリア", 1021703, 10217, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.781, 1, "2030/01/01 14:59:59", -285.0, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 139501, 3, 102, "2026/05/31 12:00:00", "リリ", 1021704, 10217, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.529, 2, "2030/01/01 14:59:59", -285.0, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 139601, 1, 202, "2026/05/31 12:00:00", "クリア", 1021705, 10217, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.195, 3, "2030/01/01 14:59:59", -285.0, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 139701, 2, 302, "2026/05/31 12:00:00", "プレシア", 1021706, 10217, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (12.43, 2, "2030/01/01 14:59:59", -285.0, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 139902, 3, 101, "2026/06/30 12:00:00", "ルイズマリー", 1021801, 10218, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.35, 2, "2030/01/01 14:59:59", -285.0, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 140001, 3, 201, "2026/06/30 12:00:00", "クレジッタ", 1021802, 10218, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (10.23, 1, "2030/01/01 14:59:59", -285.0, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 140102, 5, 101, "2026/07/31 12:00:00", "フブキ", 1021901, 10219, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.584, 1, "2030/01/01 14:59:59", -285.0, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 140201, 2, 201, "2026/07/31 12:00:00", "ヴァンピィ", 1021902, 10219, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.8, 6, "2030/01/01 14:59:59", -285.0, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 126401, 3, 201, "2026/08/31 12:00:00", "クローチェ", 1022001, 10220, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.9, 4, "2030/01/01 14:59:59", -285.0, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 127802, 3, 101, "2026/08/31 12:00:00", "ヴルム", 1022002, 10220, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4.49, 2, "2030/01/01 14:59:59", -285.0, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 140602, 1, 202, "2026/08/31 12:00:00", "クローチェ", 1022003, 10220, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9.42, 1, "2030/01/01 14:59:59", -285.0, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 140501, 3, 102, "2026/08/31 12:00:00", "ヴルム", 1022004, 10220, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.0, 4, "2030/01/01 14:59:59", -285.0, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 140402, 1, 301, "2026/08/31 12:00:00", "リーザ", 1022005, 10220, 0.0, 61);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.414, 1, "2030/01/01 14:59:59", -416.5, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 190805, 2, 1, "2026/04/10 12:00:00", "カリン", 2000001, 2, 0.0, 62);
